mapper.select:
SELECT cd.course_id, cd.visit_order, COALESCE(dt.name, '이름 없는 여행지') AS destination_name FROM course_destinations cd JOIN destinations d ON d.id = cd.destination_id LEFT JOIN destination_translations dt ON dt.destination_id = d.id AND dt.language_code = 'ko' WHERE cd.course_id IN
#{courseId}
ORDER BY cd.course_id ASC, cd.visit_order ASC, cd.id ASC

